
import fs from 'fs';
import { v4 as uuidv4 } from 'uuid';

const invalidUsers = JSON.parse(fs.readFileSync('invalid_users.json', 'utf8'));

let migrationSQL = `-- Users Table UUID Migration
-- Generated by Antigravity Agent
-- Date: ${new Date().toISOString()}

BEGIN;

-- 1. Data Correction (Fix 4 Invalid Rows)
`;

let rollbackSQL = `-- Users Table UUID Rollback
-- Generated by Antigravity Agent

BEGIN;

-- 1. Revert Type (UUID -> TEXT)
ALTER TABLE users ALTER COLUMN id TYPE text;

-- 2. Drop Default
ALTER TABLE users ALTER COLUMN id DROP DEFAULT;

-- 3. Restore Legacy IDs
`;

invalidUsers.forEach(u => {
    const newUUID = uuidv4();
    migrationSQL += `UPDATE users SET id = '${newUUID}' WHERE id = '${u.id}'; -- Was: ${u.username}\n`;
    rollbackSQL += `UPDATE users SET id = '${u.id}' WHERE id = '${newUUID}'; -- Restore ${u.username}\n`;
});

migrationSQL += `
-- 2. Schema Hardening
-- Add Default Value
ALTER TABLE users ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- 3. Type Conversion
-- This will fail if any non-UUIDs remain.
ALTER TABLE users ALTER COLUMN id TYPE uuid USING id::uuid;

COMMIT;
`;

rollbackSQL += `
COMMIT;
`;

fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_migration.sql', migrationSQL);
fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_rollback.sql', rollbackSQL);

console.log("Generated migration and rollback scripts.");
